/// <summary>
/// MPJ_30715 Purchase Order Cancel
/// </summary>
[DataContractAttribute]
public class METPurchLineIntegrationUpdateContract
{
    DataAreaId  dataAreaId;
    AccountNum  vendorAccount;
    PurchId     purchaseOrderNumber;
    TradeLineNumber     lineNum;

}

Method.Source:
    [DataMemberAttribute('dataAreaId')]
    public DataAreaId parmDataAreaId(DataAreaId  _dataAreaId = dataAreaId)
    {
        dataAreaId = _dataAreaId;

        return dataAreaId;
    }

    [DataMemberAttribute('vendorAccount')]
    public AccountNum  parmVendorAccount(AccountNum  _vendorAccount = vendorAccount)
    {
        vendorAccount = _vendorAccount;

        return vendorAccount;
    }

[DataMemberAttribute('purchaseOrderNumber')]
public PurchId parmPurchaseOrderNumber(PurchId _purchaseOrderNumber = purchaseOrderNumber)
{
    purchaseOrderNumber = _purchaseOrderNumber;
    
    return purchaseOrderNumber;
}

    [DataMemberAttribute('lineNum')]
    public TradeLineNumber parmLineNum(TradeLineNumber _lineNum = lineNum)
    {
        lineNum = _lineNum;

        return lineNum;
    }
